import { loadFont } from "@remotion/google-fonts/InterTight";
import React from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";
import { VexaSymbol } from "./VexaPro";

// VEXA PRO · versão clean branca (pedido: "clean branca, sem ser dark"), mesmas cenas e tempos de VexaRef.tsx.
// VEXA PRO · roteiro de 40 s no modelo do reel de referência (@suamarca, (arquivo do cliente)).
// Voz: (arquivo do cliente) (mp3 do o diretor, o locutor, 38,8 s). Tempos = tempos da voz; o vídeo tem LEAD de entrada.
// Do modelo: fundo preto com clarões nos cantos, celular 3D, cartão que destaca e desfoca o resto, frase palavra a palavra que se
// recentraliza, extrato que rola com desfoque de movimento, cartão-resumo, marca saindo de trás do símbolo, corte lateral, mãozinha.
// Da Vexa: roxo degradê e símbolo VP. Todos os valores na tela são ilustrativos, e o fecho avisa isso.

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const VXB_FPS = 30;
const LEAD = 0.2;
export const VXB_FRAMES = Math.round(40.6 * VXB_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.76, 0, 0.24, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const f = (n: number, d = 2) => n.toFixed(d);
const brl = (v: number) => "R$ " + v.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const BG = "#FFFFFF";
const CARD = "#FFFFFF";
const CARD2 = "#F3F0FA";
const LINE = "rgba(30,20,60,0.09)";
const PURPLE = "#7C3AED";
const VIOLET = "#7C3AED";
const WHITE = "#FFFFFF";
const INK = "#15121D";
const SOFT = "#2A2634";
const GREY = "#7D7889";
const DIM = "#B5B1C2";
const SHADOW = "0 30px 70px rgba(50,30,110,0.14), 0 4px 14px rgba(50,30,110,0.07)";

// clarões nos cantos, que andam devagar
const Ambient: React.FC<{ t: number; a?: number; b?: number }> = ({ t, a = 0.34, b = 0.16 }) => (
  <AbsoluteFill style={{ background: BG }}>
    <div style={{ position: "absolute", left: -520 + Math.sin(t * 0.5) * 90, top: -520 + Math.cos(t * 0.4) * 70, width: 1300, height: 1300, borderRadius: 1300, background: `radial-gradient(circle, rgba(124,58,237,${f(a * 0.24, 3)}) 0%, rgba(124,58,237,0) 68%)` }} />
    <div style={{ position: "absolute", right: -560 + Math.cos(t * 0.45) * 80, bottom: -480 + Math.sin(t * 0.55) * 80, width: 1300, height: 1300, borderRadius: 1300, background: `radial-gradient(circle, rgba(192,38,211,${f(b * 0.25, 3)}) 0%, rgba(192,38,211,0) 68%)` }} />
  </AbsoluteFill>
);

// desfoque em uma direção só (o rastro da rolagem e do corte lateral)
const DirBlur: React.FC<{ id: string; x?: number; y?: number; style?: React.CSSProperties; children: React.ReactNode }> = ({ id, x = 0, y = 0, style, children }) => {
  const on = x > 0.2 || y > 0.2;
  return (
    <div style={{ position: "absolute", inset: 0, filter: on ? `url(#${id})` : undefined, ...style }}>
      {on ? <svg width={0} height={0} style={{ position: "absolute" }}><filter id={id} x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation={`${f(x, 1)} ${f(y, 1)}`} /></filter></svg> : null}
      {children}
    </div>
  );
};

// palavra que abre espaço na linha: as anteriores andam e a frase fica sempre centralizada
const Word: React.FC<{ t: number; at: number; c?: string; out?: number; children: React.ReactNode }> = ({ t, at, c = INK, out, children }) => {
  const e = k(t, at, 0.4);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return (
    <div style={{ display: "inline-grid", gridTemplateColumns: `${f(e, 4)}fr`, opacity: 1 - o }}>
      <div style={{ minWidth: 0, overflow: "hidden", padding: "0.16em 0", margin: "-0.16em 0" }}>
        <span style={{ display: "inline-block", padding: "0 0.13em", color: c, opacity: Math.min(1, e * 1.5), filter: e < 1 ? `blur(${f((1 - e) * 12, 1)}px)` : undefined, whiteSpace: "nowrap" }}>{children}</span>
      </div>
    </div>
  );
};
const Line: React.FC<{ top: number; size: number; children: React.ReactNode; weight?: number; style?: React.CSSProperties }> = ({ top, size, children, weight = 600, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", alignItems: "center", fontFamily: F, fontWeight: weight, fontSize: size, letterSpacing: "-0.03em", lineHeight: 1.1, ...style }}>{children}</div>
);
// entrada de cartão: sobe, desfocado, e assenta
const rise = (t: number, at: number, y = 50, out?: number): React.CSSProperties => {
  const e = k(t, at, 0.5);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return { opacity: Math.min(1, e * 1.6) * (1 - o), transform: `translateY(${f((1 - e) * y, 1)}px) scale(${f(0.97 + 0.03 * e, 4)})`, filter: e < 1 || o > 0 ? `blur(${f((1 - e) * 10 + o * 10, 1)}px)` : undefined };
};
const Hand: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" style={{ filter: "drop-shadow(0 8px 14px rgba(40,30,80,0.3))" }}>
    <path d="M18 11V10a2 2 0 0 0-4 0M14 10V9a2 2 0 0 0-4 0v.5M10 9.500V4a2 2 0 0 0-4 0v10l-1.600-1.600a2 2 0 0 0-2.830 2.820l3.600 3.600C6.650 20.300 8.300 22 12 22h2a8 8 0 0 0 8-8v-3a2 2 0 0 0-4 0" fill={WHITE} stroke="#17141F" strokeWidth={1.4} strokeLinejoin="round" strokeLinecap="round" />
  </svg>
);
const Ring: React.FC<{ t: number; at: number; x: number; y: number; r?: number; c?: string }> = ({ t, at, x, y, r = 170, c = VIOLET }) => {
  if (t < at || t > at + 0.55) return null;
  const p = lin(t, at, at + 0.55), R = 30 + p * r;
  return <div style={{ position: "absolute", left: x - R, top: y - R, width: 2 * R, height: 2 * R, borderRadius: 999, border: `4px solid ${c}`, opacity: 0.8 * (1 - p) }} />;
};
// marca: o símbolo bate grande, encolhe e o nome sai de trás dele, como no modelo
const Brand: React.FC<{ t: number; at: number; nameAt: number; tagAt?: number; id: string; size?: number }> = ({ t, at, nameAt, tagAt, id, size = 130 }) => {
  const e = pop(t, at, 0.42);
  const shrink = k(t, at + 0.22, 0.4);
  const n = k(t, nameAt, 0.5);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 860, display: "flex", flexDirection: "column", alignItems: "center", gap: 34 }}>
      <div style={{ display: "flex", alignItems: "center", opacity: Math.min(1, e * 2) }}>
        <div style={{ position: "relative", zIndex: 2, transform: `scale(${f(e * mix(1.9, 1, shrink), 4)})` }}><VexaSymbol s={size * 1.12} id={id} glow={0.55} /></div>
        <div style={{ display: "grid", gridTemplateColumns: `${f(n, 4)}fr`, marginLeft: size * 0.14 * n }}>
          <div style={{ minWidth: 0, overflow: "hidden" }}>
            <span style={{ display: "inline-block", fontFamily: F, fontWeight: 700, fontSize: size, lineHeight: 1.15, letterSpacing: "-0.04em", color: INK, opacity: n, transform: `translateX(${f((1 - n) * -70, 1)}px)` }}>vexa</span>
          </div>
        </div>
      </div>
      {tagAt !== undefined ? <div style={{ fontFamily: F, fontWeight: 600, fontSize: 48, letterSpacing: "-0.02em", color: VIOLET, ...rise(t, tagAt, 20) }}>Tráfego & Performance</div> : null}
    </div>
  );
};

// ───────── A · você sabe quanto investiu em anúncio: celular 3D e o cartão que destaca ─────────
const NOTES: [string, string, string][] = [["Campanha ativa", "Conjunto 1 · público amplo", "− R$ 142,50"], ["Campanha ativa", "Conjunto 2 · remarketing", "− R$ 96,80"], ["Campanha ativa", "Pesquisa · Google", "− R$ 118,30"]];
const A: React.FC<{ t: number }> = ({ t }) => {
  const spin = k(t, -0.15, 1.1);
  const push = io(t, 0.75, 1.85);
  const focus = lin(t, 1.3, 1.75);
  const val = 5000 * interpolate(t, [0.1, 1.75], [0.2, 1], { ...cl, easing: OUT });
  return (
    <AbsoluteFill>
      <Ambient t={t} a={0.5} b={0.3} />
      <div style={{ position: "absolute", left: 540, top: 960, width: 0, height: 0, perspective: 1900 }}>
        <div style={{ position: "absolute", width: 0, height: 0, transformStyle: "preserve-3d", transform: `translateY(${f(mix(30, 560, push), 1)}px) scale(${f(mix(0.55, 1, spin) * mix(1, 1.72, push), 4)}) rotateY(${f(mix(88, -9, spin) * (1 - push) + Math.sin(t * 0.8) * 1.5, 2)}deg) rotateX(${f(mix(10, 4, spin) * (1 - push), 2)}deg) rotateZ(${f(mix(9, -5, spin) * (1 - push), 2)}deg)` }}>
          {/* corpo e tela */}
          <div style={{ position: "absolute", left: -280, top: -590, width: 560, height: 1180, borderRadius: 86, background: "#ECEAF1", padding: 12, boxSizing: "border-box", boxShadow: `inset 0 0 0 3px #CFCBDA, ${SHADOW}`, filter: focus > 0 ? `blur(${f(focus * 9, 1)}px)` : undefined, opacity: mix(1, 0.72, focus) }}>
            <div style={{ position: "relative", width: "100%", height: "100%", borderRadius: 74, overflow: "hidden", background: "linear-gradient(180deg, #FBFAFF 0%, #F0EAFF 58%, #D9CBFF 100%)", fontFamily: F, color: INK }}>
              {[[90, 900, 120, 0.8], [330, 820, 170, 0.7], [210, 1020, 190, 0.6], [440, 1000, 110, 0.65], [70, 1060, 90, 0.5]].map(([x, y, s, o], i) => <div key={i} style={{ position: "absolute", left: x - s / 2 + Math.sin(t + i) * 10, top: y - s / 2, width: s, height: s, borderRadius: s, background: i % 2 ? "#C026D3" : "#7C3AED", opacity: o * 0.5, filter: "blur(20px)" }} />)}
              <div style={{ position: "absolute", left: "50%", top: 22, width: 150, height: 40, marginLeft: -75, borderRadius: 30, background: "#000" }} />
              <div style={{ position: "absolute", left: 0, right: 0, top: 100, textAlign: "center", fontWeight: 600, fontSize: 28, color: "rgba(21,18,29,0.7)" }}>sexta-feira, 6 de novembro</div>
              <div style={{ position: "absolute", left: 0, right: 0, top: 130, textAlign: "center", fontWeight: 700, fontSize: 130, letterSpacing: "-0.04em" }}>18:42</div>
              {NOTES.map(([a, b, c], i) => (
                <div key={i} style={{ position: "absolute", left: 28, right: 28, top: 480 + i * 122, height: 108, borderRadius: 26, background: "rgba(255,255,255,0.92)", boxShadow: "0 8px 22px rgba(50,30,110,0.1)", display: "flex", alignItems: "center", gap: 14, padding: "0 22px", ...rise(t, 0.55 + i * 0.16, 24) }}>
                  <VexaSymbol s={40} id={`vxb-n${i}`} />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600, fontSize: 25 }}>{a}</div>
                    <div style={{ fontWeight: 500, fontSize: 20, color: GREY }}>{b}</div>
                  </div>
                  <div style={{ fontWeight: 600, fontSize: 22, color: VIOLET }}>{c}</div>
                </div>
              ))}
            </div>
          </div>
          {/* o cartão do investimento, sempre nítido */}
          <div style={{ position: "absolute", left: -252 - 26 * focus, top: -310 - 16 * focus, width: 504 + 52 * focus, height: 170, borderRadius: 30, background: "#FFFFFF", boxShadow: focus > 0 ? SHADOW : undefined, padding: "22px 26px", boxSizing: "border-box", fontFamily: F, color: INK }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, fontWeight: 600, fontSize: 21 }}><VexaSymbol s={26} id="vxb-w" />Investido em anúncios</div>
            <div style={{ fontWeight: 700, fontSize: 56, letterSpacing: "-0.03em", marginTop: 6 }}>{brl(val)}</div>
            <div style={{ height: 8, borderRadius: 8, background: "rgba(30,20,60,0.1)", marginTop: 8 }}><div style={{ width: `${f((val / 5000) * 72, 1)}%`, height: "100%", borderRadius: 8, background: VIOLET }} /></div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── B · mas sabe quanto custou cada cliente? ─────────
const B: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill>
    <Ambient t={t} a={0.22} b={0.06} />
    <Line top={850} size={80}>
      <Word t={t} at={2.83}>Mas</Word><Word t={t} at={3.03}>sabe</Word><Word t={t} at={3.41}>quanto</Word>
    </Line>
    <Line top={960} size={80}>
      <Word t={t} at={3.77}>custou</Word><Word t={t} at={4.27}>cada</Word>
    </Line>
    <Line top={1070} size={80}>
      <Word t={t} at={4.57} c={VIOLET}>cliente?</Word>
      <Word t={t} at={4.72}>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 10, fontSize: 40, fontWeight: 600, color: INK, background: "rgba(124,58,237,0.1)", border: `2px solid ${VIOLET}`, borderRadius: 60, padding: "10px 24px", verticalAlign: "middle" }}><VexaSymbol s={32} id="vxb-chip" />R$ ?,??</span>
      </Word>
    </Line>
  </AbsoluteFill>
);

// ───────── C · o extrato que rola e o cartão-resumo ─────────
type Row = [string, string, string, number];
const LEDGER: { title: string; total: number; rows: Row[] }[] = [
  { title: "Cliques sem conversa", total: 1300, rows: [["12", "Público errado", "campanha sem segmentação", 620], ["09", "Anúncio sem oferta clara", "muito clique, nenhuma mensagem", 410], ["05", "Clique de curioso", "só veio olhar", 270]] },
  { title: "Conversas sem venda", total: 900, rows: [["14", "Cliente sem resposta", "mensagem ficou pra depois", 400], ["11", "Orçamento esquecido", "sem retorno há 6 dias", 300], ["06", "Atendimento demorado", "cliente desistiu na fila", 200]] },
  { title: "Site lento", total: 800, rows: [["18", "Página demorou pra abrir", "saiu antes de carregar", 380], ["16", "Botão que não funciona", "no celular", 240], ["13", "Formulário travado", "pedido não enviado", 180]] },
];
const ROWH = 216;
const secH = (i: number) => 112 + LEDGER[i].rows.length * ROWH + 66;
const secY = (i: number) => LEDGER.slice(0, i).reduce((s, _, j) => s + secH(j), 0);
const scrollAt = (t: number) => mix(0, secY(1), io(t, 7.2, 7.6)) + mix(0, secY(2) - secY(1), io(t, 9.45, 9.85));
const C: React.FC<{ t: number }> = ({ t }) => {
  const dy = Math.abs(scrollAt(t + 1 / VXB_FPS) - scrollAt(t));
  const enter = io(t, 5.28, 5.68);
  const y = scrollAt(t) + (1 - enter) * 700;
  const blurY = Math.min(46, dy * 0.42) + (1 - enter) * (enter > 0 && enter < 1 ? 26 : 0);
  const left = 5000 - 1300 * lin(t, 5.75, 7.1) - 900 * lin(t, 7.6, 9.2) - 800 * lin(t, 9.9, 11.6);
  const card = k(t, 12.22, 0.55);
  const pv = lin(t, 13.97, 14.2);
  const out = lin(t, 14.5, 14.76);
  return (
    <AbsoluteFill style={{ fontFamily: F, color: INK }}>
      <Ambient t={t} a={0.2} b={0.07} />
      <div style={{ position: "absolute", inset: 0, filter: card > 0 ? `blur(${f(card * 7, 1)}px)` : undefined, opacity: mix(1, 0.42, card) }}>
        <div style={{ position: "absolute", left: 120, right: 120, top: 380, display: "flex", justifyContent: "space-between", alignItems: "baseline", ...rise(t, 5.3, 16) }}>
          <span style={{ fontWeight: 500, fontSize: 30, color: GREY }}>Investiu R$ 5.000,00</span>
          <span style={{ fontWeight: 500, fontSize: 30, color: GREY }}>sobra <span style={{ fontWeight: 700, fontSize: 56, color: INK, letterSpacing: "-0.03em" }}>{brl(left)}</span></span>
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 470, bottom: 0, overflow: "hidden", WebkitMaskImage: "linear-gradient(180deg, transparent 0, #000 50px)" }}>
          <DirBlur id="vxb-led" y={blurY}>
            <div style={{ position: "absolute", left: 120, width: 840, top: 60 - y }}>
              {LEDGER.map((s, i) => (
                <div key={i} style={{ height: secH(i) }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", height: 90 }}>
                    <span style={{ fontWeight: 700, fontSize: 50, letterSpacing: "-0.03em" }}>{s.title}</span>
                    <span style={{ fontWeight: 500, fontSize: 30, color: GREY, whiteSpace: "nowrap" }}>− {brl(s.total)}</span>
                  </div>
                  {s.rows.map(([d, a, b, v], j) => (
                    <div key={j} style={{ height: ROWH - 16, marginBottom: 16, borderRadius: 30, background: CARD, boxShadow: `inset 0 0 0 2px ${LINE}`, display: "flex", alignItems: "center", gap: 26, padding: "0 28px", boxSizing: "border-box" }}>
                      <div style={{ width: 104, height: 128, borderRadius: 24, background: CARD2, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                        <span style={{ fontWeight: 700, fontSize: 40 }}>{d}</span><span style={{ fontWeight: 600, fontSize: 18, color: GREY }}>NOV</span>
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: 600, fontSize: 38, letterSpacing: "-0.025em", whiteSpace: "nowrap" }}>{a}</div>
                        <div style={{ fontWeight: 500, fontSize: 27, color: GREY, whiteSpace: "nowrap", marginTop: 6 }}>{b}</div>
                      </div>
                      <div style={{ fontWeight: 600, fontSize: 31, whiteSpace: "nowrap" }}>− R$ {v}</div>
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </DirBlur>
        </div>
      </div>
      {/* cartão-resumo */}
      <div style={{ position: "absolute", left: 120, top: 650, width: 840, height: 620, borderRadius: 44, background: mix(0, 1, out) > 0 ? `rgb(${f(mix(255, 124, out), 0)},${f(mix(255, 58, out), 0)},${f(mix(255, 237, out), 0)})` : "#FFFFFF", boxShadow: `inset 0 0 0 2px ${LINE}, ${SHADOW}`, padding: "54px 56px", boxSizing: "border-box", opacity: Math.min(1, card * 1.8) * (1 - lin(t, 14.62, 14.8)), transform: `translateY(${f((1 - card) * 200, 1)}px) scale(${f(mix(0.94, 1, card) * mix(1, 1.04, lin(t, 12.3, 14.5)) * mix(1, 1.22, out), 4)})` }}>
        <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 500, fontSize: 36, color: GREY }}><span>Investido</span><span style={{ color: INK, fontWeight: 600 }}>{brl(5000)}</span></div>
        <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 500, fontSize: 36, color: GREY, marginTop: 24 }}><span>Consumido</span><span style={{ color: INK, fontWeight: 600 }}>− {brl(3000)}</span></div>
        <div style={{ display: "flex", gap: 8, height: 18, marginTop: 40 }}>
          <div style={{ width: `${f(40 * k(t, 12.7, 0.8), 1)}%`, borderRadius: 9, background: pv > 0 ? VIOLET : "#C9C4D6" }} />
          {[26, 18, 16].map((w, i) => <div key={i} style={{ width: `${f(w * k(t, 12.9 + i * 0.16, 0.6), 1)}%`, borderRadius: 9, background: "#DDD9E6" }} />)}
        </div>
        <div style={{ height: 2, background: LINE, marginTop: 44 }} />
        <div style={{ fontWeight: 600, fontSize: 38, marginTop: 44, color: pv > 0 ? VIOLET : GREY }}>Virou resultado</div>
        <div style={{ fontWeight: 700, fontSize: 132, letterSpacing: "-0.045em", lineHeight: 1.15 }}>R$ 2.000<span style={{ fontSize: 66, color: GREY, letterSpacing: "-0.02em" }}>,00</span></div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── D · não adianta só aparecer; tem que aparecer na hora certa, pra quem já está pronto pra comprar ─────────
const D: React.FC<{ t: number }> = ({ t }) => {
  if (t < 16.36) {
    return (
      <AbsoluteFill>
        <Ambient t={t} a={0.3} b={0.08} />
        <Line top={860} size={92}><Word t={t} at={14.82}>Não</Word><Word t={t} at={14.97}>adianta</Word><Word t={t} at={15.42}>só</Word></Line>
        <Line top={980} size={118} weight={700}><Word t={t} at={15.6} c={VIOLET}>aparecer.</Word></Line>
      </AbsoluteFill>
    );
  }
  // o relógio corre e para em 18:42, a hora do celular da abertura
  const run = interpolate(t, [16.4, 17.5], [430, 1122], { ...cl, easing: Easing.bezier(0.5, 0, 0.1, 1) });
  const hh = String(Math.floor(run / 60)).padStart(2, "0"), mm = String(Math.floor(run % 60)).padStart(2, "0");
  const hit = k(t, 17.48, 0.35);
  const z = mix(0.92, 1.05, lin(t, 16.36, 19.8));
  const buyer = k(t, 17.96, 0.5);
  return (
    <AbsoluteFill style={{ fontFamily: F, color: INK }}>
      <Ambient t={t} a={0.24 + 0.16 * hit} b={0.1} />
      <Line top={250} size={66}><Word t={t} at={16.43}>Tem</Word><Word t={t} at={16.54}>que</Word><Word t={t} at={16.61}>aparecer</Word></Line>
      <Line top={335} size={66}><Word t={t} at={17.06}>na</Word><Word t={t} at={17.18} c={VIOLET}>hora</Word><Word t={t} at={17.48} c={VIOLET}>certa,</Word></Line>
      <div style={{ position: "absolute", left: 0, right: 0, top: 500, height: 1100, transformOrigin: "540px 500px", transform: `scale(${f(z, 4)})` }}>
