// Identidade do Instagram @suamarca: fundo preto-azulado, roxo degradê, símbolo VP, títulos em caixa alta muito grossos,
// objetos escuros com brilho roxo por trás (o brilho é da marca). Telas, anúncios e painéis são ilustrativos, sem números.
// Limpo: o texto entra e fica parado; o movimento contínuo fica nos objetos e na câmera de cada cena.
// Tempos = tempos da locução (t = 0 é o começo do mp3; o vídeo tem LEAD de entrada).

const { fontFamily: H } = loadFont("normal", { weights: ["800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: F } = loadInter("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const VXP_FPS = 30;
const LEAD = 0.2;
export const VXP_FRAMES = Math.round(55.2 * VXP_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));
const f = (n: number, d = 2) => n.toFixed(d);

const BG = "#06050D";
const CARD = "#110E22";
const CARD2 = "#191433";
const LINE = "#2A2350";
const PURPLE = "#7C3AED";
const VIOLET = "#9D5CFF";
const LILAC = "#CDB8FF";
const GREY = "#8E89A8";
const DIM = "#4A4566";
const WHITE = "#FFFFFF";
const GREEN = "#2BD67B";

// trocas de cena (tempo da voz)
const T2 = 7.55, T3 = 11.9, T4 = 17.55, T5 = 21.6, T6 = 26.85, T7 = 28.95, T8 = 35.45, T9 = 40.85, T10 = 46.15;

// ───────── marca ─────────
const VP_PATH = "M18 25 L33 25 L51.5 59 L47 25 L71 25 C79.5 25 84.5 31 84.5 39.5 L84.5 45.5 C84.5 54 79 60 70.5 60 L60.5 60 L49 86 Z M57.5 37 L69 37 C71.2 37 72.4 38.6 72.4 41 L72.4 43 C72.4 45.4 71.2 47 69 47 L56.6 47 Z";
export const VexaSymbol: React.FC<{ s: number; id: string; glow?: number }> = ({ s, id, glow = 0 }) => (
  <svg width={s} height={s} viewBox="10 18 82 76" style={{ overflow: "visible", filter: glow > 0 ? `drop-shadow(0 0 ${f(s * 0.08 * glow, 1)}px rgba(157,92,255,${f(0.75 * glow)}))` : undefined }}>
    <defs>
      <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stopColor="#B57BFF" />
        <stop offset="0.55" stopColor="#8B45F5" />
        <stop offset="1" stopColor="#6526D9" />
      </linearGradient>
    </defs>
    <path d={VP_PATH} fill={`url(#${id})`} fillRule="evenodd" />
  </svg>
);
const Symbol = VexaSymbol;

// brilho roxo atrás do objeto principal (identidade dos posts)
const Glow: React.FC<{ x?: number; y: number; r?: number; a?: number }> = ({ x = 540, y, r = 620, a = 0.32 }) => (
  <div style={{ position: "absolute", left: x - r, top: y - r, width: r * 2, height: r * 2, borderRadius: r * 2, background: `radial-gradient(circle, rgba(124,58,237,${f(a, 3)}) 0%, rgba(124,58,237,0) 64%)` }} />
);

// ───────── texto ─────────
const blurIn = (t: number, at: number, out?: number, d = 0.38): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${f((1 - e) * 14 + o * 12, 1)}px)`,
    transform: `scale(${f(0.9 + 0.1 * e, 4)})`,
  };
};
// título em caixa alta grossa; a linha de destaque vem em roxo. O tamanho encolhe para caber em 840 px.
type L = [string, number, boolean?];
const fit = (s: string, size: number) => Math.min(size, 840 / (s.length * 0.63));
const Title: React.FC<{ t: number; items: L[]; size: number; top: number; out?: number; color?: string }> = ({ t, items, size, top, out, color = WHITE }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.02 }}>
    {items.map(([w, at, hl], i) => {
      const fs = fit(w, size);
      return (
        <div key={i} style={{ fontFamily: H, fontWeight: 900, fontSize: fs, lineHeight: 1.04, letterSpacing: "-0.015em", textTransform: "uppercase", whiteSpace: "nowrap", color: hl ? VIOLET : color, textShadow: hl ? `0 0 ${f(fs * 0.3, 0)}px rgba(157,92,255,0.45)` : undefined, ...blurIn(t, at, out) }}>
          {w}
        </div>
      );
    })}
  </div>
);
// linha pequena em caixa alta, como nos posts ("NA VEXA, GERAMOS…")
const Kicker: React.FC<{ t: number; at: number; top: number; text: string; out?: number; color?: string }> = ({ t, at, top, text, out, color = LILAC }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, textAlign: "center", fontFamily: F, fontWeight: 700, fontSize: 40, letterSpacing: "0.1em", textTransform: "uppercase", color, ...blurIn(t, at, out) }}>{text}</div>
);

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string; w?: number }>;
const sv = (s: number, c: string, ch: React.ReactNode, w = 2) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoSearch: Ico = ({ s, c, w }) => sv(s, c, <><circle cx="10.5" cy="10.5" r="6.5" /><path d="M15.5 15.5L21 21" /></>, w);
const IcoPin: Ico = ({ s, c, w }) => sv(s, c, <><path d="M12 21.5s-7-6.2-7-11.8a7 7 0 0114 0c0 5.6-7 11.8-7 11.8z" /><circle cx="12" cy="9.7" r="2.6" /></>, w);
const IcoStar: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 2.6l2.9 6 6.5.8-4.8 4.5 1.2 6.5L12 17.3l-5.8 3.1 1.2-6.5L2.6 9.4l6.5-.8z" fill={c} /></svg>
);
const IcoCart: Ico = ({ s, c, w }) => sv(s, c, <><path d="M2.5 3.5h3l2.4 11.2a1.6 1.6 0 001.6 1.3h8.3a1.6 1.6 0 001.6-1.2l1.6-6.8H6.6" /><circle cx="10" cy="20" r="1.4" /><circle cx="17.5" cy="20" r="1.4" /></>, w);
const IcoChat: Ico = ({ s, c, w }) => sv(s, c, <path d="M20.5 11.6a8.4 8.4 0 01-12.3 7.4L3.5 20.5l1.5-4.6A8.4 8.4 0 1120.5 11.6z" />, w);
const IcoCheck: Ico = ({ s, c, w }) => sv(s, c, <path d="M5 12.5l4.5 4.5L19 7.5" />, w);
const IcoBolt: Ico = ({ s, c, w }) => sv(s, c, <path d="M13.5 2.5L4.5 13.5h6.5l-1 8 9-11h-6.5z" />, w);
const IcoHeart: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 20.6s-8.6-5.1-8.6-11a4.9 4.9 0 018.6-3.2 4.9 4.9 0 018.6 3.2c0 5.9-8.6 11-8.6 11z" fill={c} /></svg>
);
const Cursor: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" style={{ filter: "drop-shadow(0 8px 14px rgba(0,0,0,0.55))" }}>
    <path d="M5 3l13.5 9.2-6.1 1.2 3.6 6.8-2.6 1.4-3.6-6.9L5 19z" fill={WHITE} stroke="#1A1530" strokeWidth={1.2} strokeLinejoin="round" />
  </svg>
);
// onda de toque
const Ripple: React.FC<{ t: number; at: number; x: number; y: number; c?: string; r?: number }> = ({ t, at, x, y, c = VIOLET, r = 220 }) => {
  if (t < at || t > at + 0.6) return null;
  const p = lin(t, at, at + 0.6);
  return <div style={{ position: "absolute", left: x - (40 + p * r), top: y - (40 + p * r), width: 2 * (40 + p * r), height: 2 * (40 + p * r), borderRadius: 999, border: `6px solid ${c}`, opacity: 0.8 * (1 - p) }} />;
};
const bar = (w: number | string, h: number, c = LINE): React.CSSProperties => ({ width: w, height: h, borderRadius: h, background: c });

// ───────── cena 1 · agora mesmo, alguém na sua cidade está pesquisando ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  if (t < 1.3) {
    const a = pop(t, 0.05, 0.35), b = pop(t, 0.42, 0.35);
    return (
      <AbsoluteFill style={{ background: BG, alignItems: "center", justifyContent: "center" }}>
        <Glow y={960} r={700} a={0.18 + 0.18 * b} />
        <div style={{ transform: `scale(${f(1.06 + 0.06 * lin(t, 0, 1.3), 4)})`, display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div style={{ fontFamily: H, fontWeight: 900, fontSize: 196, lineHeight: 0.98, color: WHITE, opacity: Math.min(1, a * 2), transform: `scale(${f(1.5 - 0.5 * a, 4)})` }}>AGORA</div>
          <div style={{ fontFamily: H, fontWeight: 900, fontSize: 196, lineHeight: 0.98, color: VIOLET, textShadow: "0 0 70px rgba(157,92,255,0.5)", opacity: Math.min(1, b * 2), transform: `translateY(${f((1 - b) * 120, 1)}px)` }}>MESMO</div>
        </div>
      </AbsoluteFill>
    );
  }
  if (t < 2.85) {
    // mapa da cidade: ruas, quadras e pinos acendendo
    const z = 0.94 + 0.1 * lin(t, 1.3, 2.85);
    const pins: [number, number, number][] = [[230, 200, 1.5], [600, 150, 1.62], [700, 420, 1.74], [190, 470, 1.86]];
    return (
      <AbsoluteFill style={{ background: BG }}>
        <Glow y={1080} a={0.26} />
        <Kicker t={t} at={1.32} top={250} text="alguém na" />
        <Title t={t} top={310} size={150} items={[["sua cidade", 1.9, true]]} />
        <div style={{ position: "absolute", left: 120, top: 640, width: 840, height: 840, borderRadius: 56, background: CARD, border: `3px solid ${LINE}`, overflow: "hidden", transform: `scale(${f(z, 4)}) rotate(${f(-2 + 3 * lin(t, 1.3, 2.85))}deg)`, boxShadow: "0 40px 90px rgba(0,0,0,0.55)" }}>
          {[150, 330, 560, 720].map((y, i) => <div key={"h" + i} style={{ position: "absolute", left: -20, right: -20, top: y, height: i % 2 ? 26 : 16, background: CARD2, transform: `rotate(${i === 2 ? -8 : 0}deg)` }} />)}
          {[120, 380, 540, 760].map((x, i) => <div key={"v" + i} style={{ position: "absolute", top: -20, bottom: -20, left: x, width: i % 2 ? 16 : 28, background: CARD2 }} />)}
          {pins.map(([x, y, at], i) => {
            const e = pop(t, at, 0.4);
            return <div key={i} style={{ position: "absolute", left: x - 40, top: y - 80, opacity: Math.min(1, e * 2), transform: `translateY(${f((1 - e) * -60, 1)}px) scale(${f(e, 3)})` }}><IcoPin s={80} c={DIM} w={2.4} /></div>;
          })}
          {/* a pessoa que procura: o pino roxo no centro, pulsando */}
          <div style={{ position: "absolute", left: 420, top: 420, width: 0, height: 0 }}>
            {[0, 0.55].map((d, i) => {
              const p = ((t - 1.95 + d) % 1.1) / 1.1;
              return t > 1.95 ? <div key={i} style={{ position: "absolute", left: -(30 + p * 200), top: -(30 + p * 200), width: 2 * (30 + p * 200), height: 2 * (30 + p * 200), borderRadius: 999, border: `5px solid ${VIOLET}`, opacity: 0.7 * (1 - p) }} /> : null;
            })}
            <div style={{ position: "absolute", left: -75, top: -140, transform: `scale(${f(pop(t, 1.93, 0.45), 3)})`, transformOrigin: "50% 100%", filter: "drop-shadow(0 0 24px rgba(157,92,255,0.7))" }}><IcoPin s={150} c={VIOLET} w={2.6} /></div>
          </div>
        </div>
      </AbsoluteFill>
    );
  }
  // a busca: a barra digita, os resultados aparecem
  const q = "perto de mim";
  const typed = q.slice(0, Math.floor(q.length * lin(t, 3.2, 4.7)));
  const up = k(t, 2.85, 0.55);
  const z = 0.95 + 0.08 * lin(t, 2.85, T2);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Glow y={1120} a={0.28} />
      <Kicker t={t} at={2.9} top={230} text="pesquisando no" out={5.1} />
      <Title t={t} top={290} size={120} items={[["Google e no", 3.7], ["Instagram", 4.4, true]]} out={5.1} />
      <Title t={t} top={250} size={128} items={[["exatamente", 5.2], ["o que você vende", 6.15, true]]} />
      <div style={{ position: "absolute", inset: 0, transformOrigin: "540px 1150px", transform: `translateY(${f((1 - up) * 700, 1)}px) scale(${f(z, 4)})` }}>
        <div style={{ position: "absolute", left: 120, top: 640, width: 840, height: 150, borderRadius: 75, background: WHITE, display: "flex", alignItems: "center", gap: 28, padding: "0 46px", boxSizing: "border-box", boxShadow: `0 0 0 ${f(8 * bump(t, 4.75, 0.5), 1)}px rgba(157,92,255,0.6), 0 30px 80px rgba(0,0,0,0.5)` }}>
          <IcoSearch s={64} c={PURPLE} w={2.6} />
          <span style={{ fontFamily: F, fontWeight: 600, fontSize: 54, color: "#1A1530", letterSpacing: "-0.02em" }}>{typed}<span style={{ opacity: Math.floor(t * 3) % 2 ? 1 : 0, color: PURPLE }}>|</span></span>
        </div>
        {[0, 1, 2].map((i) => {
          const e = pop(t, 4.85 + i * 0.16, 0.45);
          const top = 850 + i * 230;
          return (
            <div key={i} style={{ position: "absolute", left: 120, top, width: 840, height: 200, borderRadius: 40, background: CARD, border: `3px solid ${LINE}`, display: "flex", alignItems: "center", gap: 34, padding: "0 40px", boxSizing: "border-box", opacity: Math.min(1, e * 2), transform: `translateY(${f((1 - e) * 80, 1)}px) scale(${f(0.9 + 0.1 * e, 4)})` }}>
              <div style={{ width: 120, height: 120, borderRadius: 30, background: CARD2 }} />
              <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 20 }}>
                <div style={bar(`${86 - i * 12}%`, 26, "#3A3266")} />
                <div style={bar(`${62 - i * 8}%`, 18)} />
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · e está clicando no anúncio do seu concorrente ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const click = 9.05;
  const cx = interpolate(t, [T2, 8.85], [980, 700], { ...cl, easing: INOUT }), cy = interpolate(t, [T2, 8.85], [1720, 1265], { ...cl, easing: INOUT });
  const press = bump(t, click, 0.3);
  const sink = k(t, 10.35, 0.6);
  const z = 1.06 - 0.08 * lin(t, T2, T3);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Glow y={1050} a={0.22} />
      <Title t={t} top={250} size={140} items={[["está", 7.8], ["clicando", 8.65, true]]} out={9.35} />
      <Title t={t} top={250} size={120} items={[["no anúncio do", 9.5], ["seu concorrente", 10.38, true]]} />
      <div style={{ position: "absolute", inset: 0, transformOrigin: "540px 1150px", transform: `scale(${f(z, 4)}) rotate(${f(1.5 - 3 * lin(t, T2, T3))}deg)` }}>
        {/* o anúncio do concorrente */}
        <div style={{ position: "absolute", left: 150, top: 610, width: 780, height: 760, borderRadius: 48, background: CARD, border: `3px solid ${LINE}`, overflow: "hidden", transform: `scale(${f(pop(t, T2 + 0.05, 0.55) * (1 - 0.03 * press), 4)})`, boxShadow: "0 40px 90px rgba(0,0,0,0.55)" }}>
          <div style={{ position: "absolute", left: 40, top: 36, display: "flex", alignItems: "center", gap: 22 }}>
            <div style={{ width: 84, height: 84, borderRadius: 84, background: "#3B3560", color: WHITE, fontFamily: F, fontWeight: 800, fontSize: 40, display: "flex", alignItems: "center", justifyContent: "center" }}>C</div>
            <div>
              <div style={{ fontFamily: F, fontWeight: 700, fontSize: 38, color: WHITE }}>Concorrente</div>
              <div style={{ fontFamily: F, fontWeight: 500, fontSize: 28, color: GREY }}>Patrocinado</div>
            </div>
          </div>
          <div style={{ position: "absolute", left: 40, right: 40, top: 150, height: 410, borderRadius: 30, background: "linear-gradient(160deg, #2A2450, #15122B)" }}>
            <div style={{ position: "absolute", left: 60, top: 70, ...bar(360, 34, "#4A4280") }} />
            <div style={{ position: "absolute", left: 60, top: 128, ...bar(240, 34, "#4A4280") }} />
          </div>
          <div style={{ position: "absolute", left: 40, right: 40, top: 600, height: 110, borderRadius: 30, background: "#3B3560", color: WHITE, fontFamily: F, fontWeight: 700, fontSize: 42, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${f(1 - 0.06 * press, 4)})` }}>Saiba mais</div>
        </div>
        {/* a sua empresa, sem aparecer, afundando atrás */}
        <div style={{ position: "absolute", left: 150, top: 1440, width: 780, height: 170, borderRadius: 40, background: CARD, border: `3px dashed ${DIM}`, display: "flex", alignItems: "center", gap: 26, padding: "0 40px", boxSizing: "border-box", opacity: pop(t, 8.2, 0.5) * (1 - 0.65 * sink), transform: `translateY(${f(sink * 90, 1)}px) scale(${f(1 - 0.08 * sink, 4)})` }}>
          <div style={{ width: 84, height: 84, borderRadius: 84, background: CARD2, border: `3px solid ${DIM}` }} />
          <div style={{ fontFamily: F, fontWeight: 700, fontSize: 38, color: GREY }}>Sua empresa</div>
        </div>
        <Ripple t={t} at={click} x={cx} y={cy} r={260} />
        <div style={{ position: "absolute", left: cx - 18, top: cy - 12, transform: `scale(${f(1 - 0.18 * press, 3)})`, opacity: lin(t, T2, T2 + 0.2) }}><Cursor s={130} /></div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · não é falta de qualidade; é falta de aparecer na hora certa ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const SW = 14.55;
  if (t < SW) {
    const z = 0.94 + 0.08 * lin(t, T3, SW);
    return (
      <AbsoluteFill style={{ background: BG }}>
        <Glow y={1150} a={0.26} />
        <Title t={t} top={260} size={130} items={[["não é falta de", 12.2], ["qualidade", 12.98, true]]} />
        <div style={{ position: "absolute", left: 120, top: 720, width: 840, height: 760, borderRadius: 56, background: CARD, border: `3px solid ${LINE}`, transform: `scale(${f(z * pop(t, T3 + 0.05, 0.55), 4)})`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 60, boxShadow: "0 40px 90px rgba(0,0,0,0.5)" }}>
          <div style={{ display: "flex", gap: 22 }}>
            {[0, 1, 2, 3, 4].map((i) => {
              const e = pop(t, 12.45 + i * 0.15, 0.4);
              return <div key={i} style={{ transform: `scale(${f(e * (1 + 0.15 * bump(t, 13.0 + i * 0.08, 0.35)), 3)}) rotate(${f((1 - e) * -60, 1)}deg)`, filter: "drop-shadow(0 0 18px rgba(157,92,255,0.6))" }}><IcoStar s={130} c={VIOLET} /></div>;
            })}
          </div>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 26, opacity: k(t, 13.3, 0.5) }}>
            <div style={bar(520, 30, "#3A3266")} />
            <div style={bar(380, 22)} />
          </div>
        </div>
      </AbsoluteFill>
    );
  }
  // o relógio: o ponteiro corre e para na hora certa
  const hit = 16.25;
  const ang = t < hit ? (t - SW) * 420 : 420 * (hit - SW);
  const snap = k(t, hit, 0.35);
  const target = Math.ceil((420 * (hit - SW)) / 360) * 360 + 60;
  const a = t < hit ? ang : ang + (target - ang) * snap;
  const z = 0.92 + 0.12 * lin(t, SW, T4);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Glow y={1160} a={0.2 + 0.25 * bump(t, hit, 0.8)} r={680} />
      <Title t={t} top={250} size={128} items={[["é falta de aparecer", 14.7], ["na hora certa", 16.2, true]]} />
      <div style={{ position: "absolute", left: 540, top: 1160, width: 0, height: 0, transform: `scale(${f(z * pop(t, SW, 0.55), 4)})` }}>
        <div style={{ position: "absolute", left: -360, top: -360, width: 720, height: 720, borderRadius: 720, background: CARD, border: `8px solid ${LINE}`, boxSizing: "border-box", boxShadow: "0 40px 90px rgba(0,0,0,0.5)" }} />
        <svg width={720} height={720} viewBox="-360 -360 720 720" style={{ position: "absolute", left: -360, top: -360 }}>
          <circle r={300} fill="none" stroke={VIOLET} strokeWidth={34} strokeDasharray={`${f(1885 * 0.12 * k(t, 15.4, 0.6), 0)} 1885`} transform="rotate(-60)" style={{ filter: "drop-shadow(0 0 16px rgba(157,92,255,0.8))" }} />
          {[...Array(12)].map((_, i) => {
            const r = (i * 30 * Math.PI) / 180;
