// trocas variadas: círculo, subida, losango, metades, descida, lateral, faixa inclinada, da direita, círculo
const SCENES: [number, React.FC<{ t: number }>, (p: number) => string][] = [
  [-9, S1, () => "none"],
  [T2, S2, (p) => `circle(${f(p * 125, 1)}% at 85% 85%)`],
  [T3, S3, (p) => `inset(${f((1 - p) * 100)}% 0 0 0)`],
  [T4, S4, (p) => `polygon(50% ${f(50 - p * 100, 1)}%, ${f(50 + p * 100, 1)}% 50%, 50% ${f(50 + p * 100, 1)}%, ${f(50 - p * 100, 1)}% 50%)`],
  [T5, S5, (p) => `inset(0 ${f((1 - p) * 50)}% 0 ${f((1 - p) * 50)}%)`],
  [T6, S6, (p) => `inset(0 0 ${f((1 - p) * 100)}% 0)`],
  [T7, S7, (p) => `inset(0 ${f((1 - p) * 100)}% 0 0)`],
  [T8, S8, (p) => `polygon(0 0, ${f(p * 170, 1)}% 0, ${f(p * 170 - 60, 1)}% 100%, 0 100%)`],
  [T9, S9, (p) => `inset(0 0 0 ${f((1 - p) * 100)}%)`],
  [T10, S10, (p) => `circle(${f(p * 125, 1)}% at 50% 45%)`],
];

export const VexaPro: React.FC = () => {
  const t = useCurrentFrame() / VXP_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {SCENES.map(([at, S, clip], i) => {
        const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            <S t={t} />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

// ───────── v2 · voz sem pausas (src/voz-v2.wav, 39,8 s): as mesmas cenas, com o tempo novo convertido no antigo ─────────
export const VXP2_FRAMES = Math.round(41.5 * VXP_FPS);
const toOld = (tn: number) => (tn <= 0 ? tn : tn >= WARP[WARP.length - 1][0] ? WARP[WARP.length - 1][1] + tn - WARP[WARP.length - 1][0] : interpolate(tn, WARP.map((w) => w[0]), WARP.map((w) => w[1])));
const toNew = (to: number) => (to <= 0 ? to : to >= WARP[WARP.length - 1][1] ? WARP[WARP.length - 1][0] + to - WARP[WARP.length - 1][1] : interpolate(to, WARP.map((w) => w[1]), WARP.map((w) => w[0])));
export const VexaProV2: React.FC = () => {
  const tn = useCurrentFrame() / VXP_FPS - LEAD;
  const t = toOld(tn);
  return (
    <AbsoluteFill style={{ background: BG }}>
      {SCENES.map(([at, S, clip], i) => {
        const sn = i === 0 ? -9 : toNew(at);
        const end = i + 1 < SCENES.length ? toNew(SCENES[i + 1][0]) + 0.4 : 1e9;
        if (tn < sn || tn >= end) return null;
        const p = i === 0 ? 1 : interpolate(tn, [sn, sn + 0.36], [0, 1], { ...cl, easing: INOUT });
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            <S t={t} />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

